import { mount } from 'svelte'
import InstallHint from './InstallHint.svelte'

/** Offline support and storage protection, shared by every page. */
export function setUpPwa() {
  // sw.js is generated by the build, so the dev server has none.
  if (import.meta.env.PROD && 'serviceWorker' in navigator) {
    navigator.serviceWorker.register('./sw.js').catch(() => {})
  }
  // Asks the browser not to clear saved records when the phone runs low on space.
  // The browser decides on its own and may refuse silently; manual clearing still deletes them.
  navigator.storage?.persist?.().catch(() => {})
  // Only pages with a manifest are apps; the index page just lists them.
  if (document.querySelector('link[rel="manifest"]')) {
    mount(InstallHint, { target: document.body.appendChild(document.createElement('div')) })
  }
}
